import{_ as a,o as n,c as p,a6 as e}from"./chunks/framework.De615z8S.js";const m=JSON.parse('{"title":"跨境图片交付检查与定向返工","description":"","frontmatter":{"id":"P20","title":"跨境图片交付检查与定向返工","chapter":"13","topic":"cross-border","status":"已公开","evidence_status":"完整模板，尚未执行图像任务或流程验证","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["ecommerce-skills","visual-copywriting"],"order":120},"headers":[],"relativePath":"prompts/P20.md","filePath":"prompts/P20.md"}'),l={name:"prompts/P20.md"};function t(i,s,c,o,r,d){return n(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="p20-跨境图片交付检查与定向返工" tabindex="-1">P20 跨境图片交付检查与定向返工 <a class="header-anchor" href="#p20-跨境图片交付检查与定向返工" aria-label="Permalink to &quot;P20 跨境图片交付检查与定向返工&quot;">​</a></h1><p>类型：检查。替换项目：原商品、结果图、当前规则、准确文案与文件清单。下面提供完整填写示范，虚构商品DN01只作练习；正式使用时替换事实与素材。示范未附照片、未执行任务。</p><p><a href="./../ecommerce/cross-border-sku-delivery">逐步教程</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请对跨境图片包进行逐项检查，输出具体问题与定向返工指令，本次不自行重生成整套。</span></span>
<span class="line"><span>以下DN01／DeskNest是虚构练习数据，不代表实际品牌或商品；正式任务必须换成已核实的商品记录。</span></span>
<span class="line"><span>练习事实：带盖桌面收纳盒；白色ABS；外尺寸长220×宽150×高120 mm；可拆隔板1个。</span></span>
<span class="line"><span>发货内容：盒体1、盖子1、隔板1。文具等场景道具不随商品发货。</span></span>
<span class="line"><span>容积、耐温、承重、防水、食品接触、认证和回收属性均未知，不补相关声明。</span></span>
<span class="line"><span>图片输入如有：图1是真实商品外观依据；图2是实际细节；图3仅参考背景和构图，不使用其商品、Logo或参数。</span></span>
<span class="line"><span>未附实拍时先给素材清单和可执行方案；不要臆画正式商品或未拍摄结构。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输入另有：我提供的结果图、文件清单、市场／图片位置、当前规则记录、审定文案和实际源文件。</span></span>
<span class="line"><span>检查商品：形状、颜色、盖子、隔板、外尺寸、包装与配件数量是否和真实依据一致。</span></span>
<span class="line"><span>检查内容：单位、英文／日文、L/W/H、发货内容与道具关系；删除未知性能、认证、销量或促销声明。</span></span>
<span class="line"><span>检查渠道：主图／副图／A+／横幅是否分工正确；有当前站点出处才作规则判断，没有则列待核。</span></span>
<span class="line"><span>检查文件：实际像素、比例、格式、可打开、命名和媒体顺序；只有看到并打开源文件，才判断文字或图层是否可编辑。</span></span>
<span class="line"><span>输出表：文件／任务ID、问题位置、依据、影响、具体修改指令、需要补的素材、复查项。</span></span>
<span class="line"><span>译文错只改文字层，裁切错重排对应版式，商品结构错回到真实照片合成；不要用重做全套替代定位问题。</span></span>
<span class="line"><span>没有结果图或没有实际后台预览时明确未验证，不把计划、脚本PASS或本地缩略图当平台审核通过。</span></span>
<span class="line"><span>本次范围按上述任务执行；没有图像能力时只交方案并写明状态。</span></span>
<span class="line"><span>实际执行时保留真实商品层与准确文字，逐项核对形状、颜色、盖子、隔板、配件、单位和文字。</span></span>
<span class="line"><span>目标尺寸与工具实际输出分别报告；不把画质形容词、计划路径或未创建的PSD当作已交付结果。</span></span>
<span class="line"><span>最终列：已完成、需要补的素材、无法确认的项目、实际存在的文件与下一步。</span></span></code></pre></div><p>检查：输入角色清楚、事实与未知分开、输出范围明确，实际文件与后台状态据实记录。</p>`,5)])])}const u=a(l,[["render",t]]);export{m as __pageData,u as default};
